package com.eidolon.sc.mobile;
import org.json.*;import java.util.*;
public class AppealTests {
 static int count;interface Action{void run()throws Exception;}static void check(boolean ok,String name){if(!ok)throw new AssertionError(name);count++;System.out.println("PASS "+name);}static void rejects(Action a,String s)throws Exception{boolean no=false;try{a.run();}catch(Exception e){no=true;}check(no,s);}
 static JSONObject data()throws Exception{JSONObject d=PersonalData.fresh();Progression.upgrade(d);return d;}
 static JSONObject judged(JSONObject d,String who,boolean out)throws Exception{d.getJSONObject("affinity").put(who,80);JSONObject result=Progression.apply(d,who,who,new JSONObject().put("level",out?2:1).put("out_of_line",out),System.currentTimeMillis());JSONObject r=AppealData.record(new JSONObject().put("chatJudgment",new JSONObject().put("hurt",-result.getDouble("delta")).put("out",out)),System.currentTimeMillis());Progression.session(d,who).put("lastJudgmentKey",r.getString("key"));return r;}
 public static void main(String[] args)throws Exception{
  String day="2026-10-23";JSONObject d=data(),r=judged(d,"mano",false);check(r.getDouble("hurt")==2,"judgment record captures only actual chat loss");check(AppealData.record(new JSONObject(),1)==null,"failed or disabled judge creates no appeal record");check(AppealData.apply(d,"mano","mano",r,day,true)==2&&d.getJSONObject("affinity").getDouble("mano")==80,"appeal refunds the original chat loss");check(Progression.session(d,"mano").getJSONArray("hurt").getDouble(0)==0,"appeal removes only corresponding hurt entry");check(AppealData.left(d,day)==2,"successful appeal consumes one shared daily allowance");rejects(()->AppealData.apply(d,"mano","mano",r,day,true),"same record cannot refund twice");
  JSONObject out=data(),or=judged(out,"mano",true);AppealData.apply(out,"mano","mano",or,day,true);check(Progression.session(out,"mano").getInt("out")==0&&out.getJSONObject("affinity").getDouble("mano")==80,"one appealed out-of-line turn is removed from ending counters");
  JSONObject latest=data(),lr=judged(latest,"mano",false);Progression.session(latest,"mano").put("lastJudgmentKey","newer");rejects(()->AppealData.apply(latest,"mano","mano",lr,day,true),"mismatched latest judgment is rejected");
  JSONObject closed=data(),cr=judged(closed,"mano",false);rejects(()->AppealData.apply(closed,"mano","mano",cr,day,false),"disabled affinity rejects appeal");Progression.session(closed,"mano").put("ended",true);rejects(()->AppealData.apply(closed,"mano","mano",cr,day,true),"ended conversation cannot be reopened by appeal");check(AppealData.left(closed,day)==3&&!cr.getBoolean("appealed"),"refusal leaves daily quota and message mark untouched");
  JSONObject quota=data();for(String who:new String[]{"mano","hiori","meguru"})AppealData.apply(quota,who,who,judged(quota,who,false),day,true);JSONObject fourth=judged(quota,"tenka",false);rejects(()->AppealData.apply(quota,"tenka","tenka",fourth,day,true),"three daily appeals are shared across all characters");check(AppealData.left(quota,"2026-10-22")==0,"clock rollback cannot refill allowance");check(AppealData.left(quota,"2026-10-24")==3,"next producer date receives three allowances");
  String token=AppealData.pendingKey(d,"mano");JSONObject cancelled=new JSONObject(d.toString());AppealData.delivered(d,cancelled,"mano","");check(!AppealData.pendingKey(cancelled,"mano").isEmpty(),"cancelled or ungenerated reply does not consume explanation");JSONObject sent=new JSONObject(d.toString());AppealData.delivered(d,sent,"mano",token);check(AppealData.pendingKey(sent,"mano").isEmpty(),"matching delivered reply consumes explanation once");JSONObject newer=new JSONObject(d.toString());AppealData.root(newer).getJSONObject("explanations").put("mano",UUID.randomUUID().toString());JSONObject stale=new JSONObject(newer.toString());AppealData.delivered(newer,stale,"mano",token);check(!AppealData.pendingKey(stale,"mano").isEmpty(),"stale reply cannot consume a newer explanation");
  check(AppealData.prompt(d,"mano").contains("误会")&&AppealData.prompt(sent,"mano").isEmpty(),"explanation prompt applies until actual delivery");
  JSONObject backup=new JSONObject().put("format","eidolon-android-chats").put("version",11).put("personal",d).put("stories",new JSONArray()).put("schedules",new JSONArray()).put("writings",new JSONArray()).put("writingEvents",new JSONArray()).put("letterPlans",new JSONArray()).put("diaryAttempts",new JSONArray()).put("conversations",new JSONArray().put(new JSONObject().put("id","mano").put("character","mano").put("title","test").put("messages",new JSONArray().put(new JSONObject().put("role","user").put("text","user")).put(new JSONObject().put("role","assistant").put("text","reply").put("judgment",r)))));
  Set<String> known=new HashSet<>(Arrays.asList("mano"));BackupValidator.validate(backup,known);JSONObject restored=new JSONObject(new String(BackupCrypto.decrypt(BackupCrypto.encrypt(backup.toString().getBytes("UTF-8"),"appeal-backup".toCharArray()),"appeal-backup".toCharArray()),"UTF-8"));check(restored.getJSONObject("personal").getJSONObject("appeals").getInt("used")==1&&restored.getJSONArray("conversations").getJSONObject(0).getJSONArray("messages").getJSONObject(1).getJSONObject("judgment").getBoolean("appealed"),"encrypted backup preserves shared quota and once-only message mark");
  JSONObject bad=new JSONObject(backup.toString());bad.getJSONArray("conversations").put(bad.getJSONArray("conversations").getJSONObject(0));rejects(()->BackupValidator.validate(bad,known),"duplicate judgment keys rejected before backup import");JSONObject badRecord=new JSONObject(r.toString()).put("hurt",100);rejects(()->AppealData.validateRecord(badRecord),"unbounded refund metadata rejected");
  System.out.println("Passed "+count+" appeal checks. No API or Android runtime.");
 }
}
